import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry triu_matmul_kernel(
    .param .u64 p_a,
    .param .u64 p_b,
    .param .u64 p_c,
    .param .s32 p_n
)
{
    .shared .align 4 .b8 sh_a[1024];
    .shared .align 4 .b8 sh_b[1024];

    .reg .pred %p1, %p2, %p3, %p4;
    .reg .b32 %r_tid, %r_tx, %r_ty, %r_bx, %r_by, %r_row, %r_col, %r_n;
    .reg .b32 %r_kt, %r_ntiles, %r_kidx, %r_ridx, %r_i, %r_off, %r_t1;
    .reg .b32 %r_sha, %r_shb;
    .reg .f32 %f_sum, %f_a, %f_b, %f_zero;
    .reg .b64 %rd_a, %rd_b, %rd_c, %rd_addr;

    ld.param.u64 %rd_a, [p_a];
    ld.param.u64 %rd_b, [p_b];
    ld.param.u64 %rd_c, [p_c];
    ld.param.s32 %r_n, [p_n];

    mov.u32 %r_sha, sh_a;
    mov.u32 %r_shb, sh_b;

    mov.u32 %r_tid, %tid.x;
    and.b32 %r_tx, %r_tid, 15;
    shr.u32 %r_ty, %r_tid, 4;
    mov.u32 %r_bx, %ctaid.x;
    mov.u32 %r_by, %ctaid.y;
    shl.b32 %r_t1, %r_by, 4;
    add.u32 %r_row, %r_t1, %r_ty;
    shl.b32 %r_t1, %r_bx, 4;
    add.u32 %r_col, %r_t1, %r_tx;

    add.s32 %r_ntiles, %r_n, 15;
    shr.u32 %r_ntiles, %r_ntiles, 4;

    mov.f32 %f_sum, 0f00000000;
    mov.u32 %r_kt, 0;

$L_tile:
    setp.lt.s32 %p1, %r_kt, %r_ntiles;
    @!%p1 bra $L_done;

    shl.b32 %r_t1, %r_kt, 4;
    add.u32 %r_kidx, %r_t1, %r_tx;
    add.u32 %r_ridx, %r_t1, %r_ty;

    // Load A[row, kidx] into shared tile A
    setp.lt.s32 %p1, %r_row, %r_n;
    setp.lt.s32 %p2, %r_kidx, %r_n;
    and.pred %p3, %p1, %p2;
    mov.f32 %f_a, 0f00000000;
    mad.lo.s32 %r_off, %r_row, %r_n, %r_kidx;
    mul.wide.s32 %rd_addr, %r_off, 4;
    add.u64 %rd_addr, %rd_addr, %rd_a;
    @%p3 ld.global.f32 %f_a, [%rd_addr];
    mul.lo.s32 %r_off, %r_ty, 64;
    shl.b32 %r_t1, %r_tx, 2;
    add.s32 %r_off, %r_off, %r_t1;
    add.s32 %r_off, %r_off, %r_sha;
    st.shared.f32 [%r_off], %f_a;

    // Load B[ridx, col] into shared tile B
    setp.lt.s32 %p1, %r_ridx, %r_n;
    setp.lt.s32 %p2, %r_col, %r_n;
    and.pred %p3, %p1, %p2;
    mov.f32 %f_b, 0f00000000;
    mad.lo.s32 %r_off, %r_ridx, %r_n, %r_col;
    mul.wide.s32 %rd_addr, %r_off, 4;
    add.u64 %rd_addr, %rd_addr, %rd_b;
    @%p3 ld.global.f32 %f_b, [%rd_addr];
    mul.lo.s32 %r_off, %r_ty, 64;
    shl.b32 %r_t1, %r_tx, 2;
    add.s32 %r_off, %r_off, %r_t1;
    add.s32 %r_off, %r_off, %r_shb;
    st.shared.f32 [%r_off], %f_b;

    bar.sync 0;

    mov.u32 %r_i, 0;
$L_inner:
    setp.lt.s32 %p1, %r_i, 16;
    @!%p1 bra $L_inner_done;

    mul.lo.s32 %r_off, %r_ty, 64;
    shl.b32 %r_t1, %r_i, 2;
    add.s32 %r_off, %r_off, %r_t1;
    add.s32 %r_off, %r_off, %r_sha;
    ld.shared.f32 %f_a, [%r_off];

    mul.lo.s32 %r_off, %r_i, 64;
    shl.b32 %r_t1, %r_tx, 2;
    add.s32 %r_off, %r_off, %r_t1;
    add.s32 %r_off, %r_off, %r_shb;
    ld.shared.f32 %f_b, [%r_off];

    fma.rn.f32 %f_sum, %f_a, %f_b, %f_sum;
    add.s32 %r_i, %r_i, 1;
    bra $L_inner;

$L_inner_done:
    bar.sync 0;
    add.s32 %r_kt, %r_kt, 1;
    bra $L_tile;

$L_done:
    setp.lt.s32 %p1, %r_row, %r_n;
    setp.lt.s32 %p2, %r_col, %r_n;
    and.pred %p3, %p1, %p2;
    @!%p3 bra $L_exit;
    setp.ge.s32 %p4, %r_col, %r_row;
    mov.f32 %f_zero, 0f00000000;
    selp.f32 %f_a, %f_sum, %f_zero, %p4;
    mad.lo.s32 %r_off, %r_row, %r_n, %r_col;
    mul.wide.s32 %rd_addr, %r_off, 4;
    add.u64 %rd_addr, %rd_addr, %rd_c;
    st.global.f32 [%rd_addr], %f_a;

$L_exit:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triu_matmul_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        n = A.shape[0]
        C = torch.empty((n, n), dtype=A.dtype, device=A.device)
        module = _get_ptx_module()
        module.launch(
            "triu_matmul_kernel",
            grid=((n + 15) // 16, (n + 15) // 16, 1),
            block=(256, 1, 1),
            arguments=[A, B, C, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

